function svg(path,cls=''){return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${path}</svg>`}
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function monthISO(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`}
function monthText(iso){const t=monthFmt.format(new Date(`${String(iso).slice(0,10)}T12:00:00`));return t.charAt(0).toUpperCase()+t.slice(1)}
function monthShort(iso){return shortMonthFmt.format(new Date(`${String(iso).slice(0,10)}T12:00:00`)).replace('.','').replace(' de ',' ')}
function money(v){return moneyFmt.format(Number(v||0))}
function parseMoney(v){let s=String(v??'').trim().replace(/\s/g,'').replace(/^R\$/i,'');if(!s)return NaN;if(s.includes(',')&&s.includes('.'))s=s.replace(/\./g,'').replace(',','.');else if(s.includes(','))s=s.replace(',','.');const n=Number(s.replace(/[^0-9.-]/g,''));return Number.isFinite(n)?n:NaN}
function currentMonth(){return monthISO(new Date())}
function previousMonth(){return addMonths(currentMonth(),-1)}
function monthName(iso){return monthNameFmt.format(new Date(`${String(iso).slice(0,10)}T12:00:00`))}
function initials(name='JH'){return String(name).trim().split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase()||'JH'}
function displayName(){return state.profile?.display_name||state.session?.user?.user_metadata?.display_name||state.session?.user?.email?.split('@')[0]||'JuHelo'}
function householdId(){return state.household?.id||null}
function toast(msg,type=''){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=msg;toastRoot.appendChild(el);setTimeout(()=>el.remove(),3200)}
function setBusy(btn,busy,label='Salvando…'){if(!btn)return;if(busy){btn.dataset.oldText=btn.textContent;btn.textContent=label;btn.disabled=true}else{btn.textContent=btn.dataset.oldText||btn.textContent;btn.disabled=false}}
function safeError(err,fallback='Não foi possível concluir agora.'){console.warn(err);toast(err?.message||fallback,'error')}
function summary(){const income=state.transactions.filter(t=>t.direction==='income').reduce((s,t)=>s+Number(t.amount||0),0);const expense=state.transactions.filter(t=>t.direction==='expense').reduce((s,t)=>s+Number(t.amount||0),0);return{income,expense,result:income-expense}}
function balanceFor(boxId){return Number(state.boxBalances.find(b=>b.box_id===boxId)?.balance||0)}
function upsertTx(tx){const i=state.transactions.findIndex(x=>x.id===tx.id);if(i>=0)state.transactions[i]=tx;else state.transactions.unshift(tx)}
function isPayable(tx){return !!tx&&tx.direction==='expense'&&tx.kind!=='box_contribution'}
function syncPreviousPending(tx){if(String(tx?.month).slice(0,10)!==previousMonth()||!isPayable(tx))return;const i=state.previousPending.findIndex(x=>x.id===tx.id);if(tx.is_paid){if(i>=0)state.previousPending.splice(i,1)}else if(i>=0)state.previousPending[i]={id:tx.id,amount:tx.amount};else state.previousPending.push({id:tx.id,amount:tx.amount})}
function categoryFor(tx){if(tx?.direction==='income')return null;const key=tx?.kind==='recurring'?'recurring':tx?.kind==='box_contribution'?'box':tx?.category||'uncategorized';return {key,...(CATEGORIES[key]||CATEGORIES.uncategorized)}}
function cardFor(id){return state.cards.find(c=>c.id===id)||null}
function cardBySlug(slug){return state.cards.find(c=>c.slug===slug)||null}
function preferredCardForCategory(key){const matches=state.cards.filter(c=>(c.allowed_categories||[]).includes(key));return matches.length===1?matches[0]:null}
function cardGlyph(card){return (card?.bank||'C').trim().charAt(0).toUpperCase()||'C'}
function categoryOptions(selected=''){return `<fieldset class="category-field"><legend>Categoria</legend><div class="category-grid">${USER_EXPENSE_CATEGORIES.map(key=>{const c=CATEGORIES[key];return `<button type="button" class="category-choice ${selected===key?'is-selected':''} ${c.wide?'is-wide':''}" data-category="${key}" style="--cat:${c.color}"><span>${c.emoji}</span><strong>${esc(c.label)}</strong><i>✓</i></button>`}).join('')}</div></fieldset>`}
function categoryReadonly(key){const c=CATEGORIES[key];return `<div class="category-readonly" style="--cat:${c.color}"><span>${c.emoji}</span><div><small>Categoria</small><strong>${esc(c.label)}</strong></div></div>`}
function cardSelect(selected='',label='Cartão'){return `<label class="field card-select-field">${label}<span>opcional para Débito/Pix</span><select name="card_id" data-card-select><option value="">Sem cartão / Débito ou Pix</option>${state.cards.map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${esc(c.name)}</option>`).join('')}</select><small class="card-use-hint" data-card-hint></small></label>`}
function cardUseText(card){if(!card)return 'Sem cartão: use para Pix, débito ou dinheiro.';const cats=(card.allowed_categories||[]).map(k=>CATEGORIES[k]?.label).filter(Boolean);return cats.length?`Uso planejado: ${cats.join(' · ')}`:'Sem categoria planejada para este cartão.'}

function applyTheme(pref){localStorage.setItem('juhelo-theme-preference',pref);const dark=pref==='dark'||(pref==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);const theme=dark?'dark':'light';document.documentElement.dataset.theme=theme;document.documentElement.dataset.themePreference=pref;document.documentElement.style.colorScheme=theme;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',dark?'#0c0c0f':'#fbfafc')}
matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if((localStorage.getItem('juhelo-theme-preference')||'light')==='system')applyTheme('system')});

async function loadContext(){if(!state.session)return;const [{data:profile,error:pe},{data:membership,error:me}]=await Promise.all([db.from('profiles').select('id,display_name,avatar_url').eq('id',state.session.user.id).maybeSingle(),db.from('household_members').select('household_id,role,joined_at').eq('user_id',state.session.user.id).maybeSingle()]);if(pe)throw pe;if(me)throw me;state.profile=profile||null;if(!membership){state.household=null;state.members=[];return}const [{data:household,error:he},{data:memberRows,error:mre}]=await Promise.all([db.from('households').select('id,name,invite_code,created_at').eq('id',membership.household_id).single(),db.from('household_members').select('user_id,role,joined_at').eq('household_id',membership.household_id).order('joined_at')]);if(he)throw he;if(mre)throw mre;state.household=household;const ids=(memberRows||[]).map(x=>x.user_id);let profiles=[];if(ids.length){const{data,error}=await db.from('profiles').select('id,display_name,avatar_url').in('id',ids);if(error)throw error;profiles=data||[]}state.members=(memberRows||[]).map(m=>({...m,profile:profiles.find(p=>p.id===m.user_id)||null}))}
async function ensureRecurring(month){if(!householdId())return;const{error}=await db.rpc('ensure_recurring_for_month',{p_household_id:householdId(),p_month:month});if(error)console.warn('ensure recurring',error)}
async function loadTransactions(month=state.txMonth){if(!householdId())return;const{data,error}=await db.from('transactions').select('*').eq('household_id',householdId()).eq('month',month).order('created_at',{ascending:false});if(error)throw error;if(month===state.txMonth)state.transactions=data||[];return data||[]}
async function loadPreviousPending(){if(!householdId()){state.previousPending=[];return}const{data,error}=await db.from('transactions').select('id,amount').eq('household_id',householdId()).eq('month',previousMonth()).eq('direction','expense').eq('is_paid',false).neq('kind','box_contribution');if(error)throw error;state.previousPending=data||[]}
async function loadBoxes(){if(!householdId())return;const[{data:b,error:be},{data:bal,error:bae}]=await Promise.all([db.from('boxes').select('id,name,target_amount,target_date,is_archived,created_at').eq('household_id',householdId()).eq('is_archived',false).order('created_at'),db.from('box_balances').select('box_id,balance').eq('household_id',householdId())]);if(be)throw be;if(bae)throw bae;state.boxes=b||[];state.boxBalances=bal||[]}
async function loadGoals(){if(!householdId())return;const{data,error}=await db.from('goals').select('id,title,notes,due_date,is_completed,completed_at,sort_order,created_at').eq('household_id',householdId()).order('is_completed').order('sort_order').order('created_at');if(error)throw error;state.goals=data||[]}
async function loadCards(){if(!householdId())return;const{data,error}=await db.from('payment_cards').select('id,slug,name,bank,owner_label,color,allowed_categories,sort_order,is_active').eq('household_id',householdId()).eq('is_active',true).order('sort_order');if(error)throw error;state.cards=data||[]}
async function loadReport(start=state.reportStart,end=state.reportEnd){if(!householdId())return;state.reportLoading=true;render();try{const [{data:rows,error:re},{data:tx,error:te}]=await Promise.all([db.from('monthly_summary').select('month,total_income,total_expense,month_result').eq('household_id',householdId()).gte('month',start).lte('month',end).order('month'),db.from('transactions').select('month,amount,category,kind,direction,card_id').eq('household_id',householdId()).eq('direction','expense').neq('kind','box_contribution').gte('month',start).lte('month',end).order('month')]);if(re)throw re;if(te)throw te;state.reportRows=rows||[];state.reportTransactions=tx||[]}catch(e){safeError(e,'Não foi possível carregar o relatório.')}finally{state.reportLoading=false;render()}}
async function syncMonth(renderAfter=true){const month=state.txMonth;try{await ensureRecurring(month);await Promise.all([loadTransactions(month),loadPreviousPending()]);if(renderAfter&&month===state.txMonth)render()}catch(e){safeError(e,'Os dados foram salvos, mas a atualização da tela falhou.')}}
async function boot(){state.loading=true;render();try{await loadContext();if(state.household){state.txMonth=currentMonth();state.unpaidOnly=false;await ensureRecurring(state.txMonth);await Promise.all([loadTransactions(),loadPreviousPending(),loadBoxes(),loadGoals(),loadCards()])}}catch(e){safeError(e,'Falha ao carregar o JuHelo.')}finally{state.loading=false;render()}}

function avatarStack(){const members=state.members.length?state.members.slice(0,2):[{user_id:state.session?.user?.id,profile:{display_name:displayName()}}];return `<button class="couple-stack" data-settings-open aria-label="Abrir ajustes">${members.map((m,i)=>{const n=m.profile?.display_name||(m.user_id===state.session?.user?.id?displayName():'Pessoa');return `<span class="couple-avatar a${i+1}">${esc(initials(n))}</span>`}).join('')}${members.length>1?'<i></i>':''}</button>`}
function topbar(title){return `<header class="topbar"><h1>${esc(title)}</h1>${avatarStack()}</header>`}
function nav(){const items=[['home','Início'],['transactions','Movimentos'],['boxes','Caixinhas'],['reports','Relatórios'],['goals','Metas']];return `<nav class="bottom-nav">${items.map(([id,label])=>`<button class="nav-item ${state.tab===id?'active':''}" data-tab="${id}" aria-label="${label}"><span class="nav-icon">${svg(ICON[id])}</span><span>${label}</span></button>`).join('')}</nav>`}
function monthOptions(selected,span=18){const base=new Date(`${selected}T12:00:00`);let out='';for(let i=-span;i<=span;i++){const d=new Date(base.getFullYear(),base.getMonth()+i,1),iso=monthISO(d);out+=`<option value="${iso}" ${iso===selected?'selected':''}>${esc(monthText(iso))}</option>`}return out}
function monthControl(){return `<label class="month-control">${svg(ICON.calendar)}<select id="month-select">${monthOptions(state.txMonth)}</select></label>`}
function moneyVisible(v){return state.valuesHidden?'R$ •••••':money(v)}
function actionButton(type,label,sub,action){return `<button class="quick-card ${type}" data-action="${action}"><span>${svg(ICON[type]||ICON.goals)}</span><div><strong>${label}</strong><small>${sub}</small></div></button>`}
function txRow(tx){if(tx.direction==='income')return `<div class="tx-row"><span class="tx-icon income">${svg(ICON.income)}</span><div class="tx-copy"><strong>${esc(tx.description)}</strong><small>Receita</small></div><b>${money(tx.amount)}</b><button class="more-btn" data-edit-tx="${tx.id}" aria-label="Opções">•••</button></div>`;const cat=categoryFor(tx),card=cardFor(tx.card_id),payable=isPayable(tx),paid=tx.is_paid===true,busy=state.paymentBusy.has(tx.id);return `<div class="tx-row ${payable?'is-payable':''} ${paid?'is-paid':'is-unpaid'}" data-transaction-id="${tx.id}">${payable?`<button class="payment-check ${paid?'checked':''}" data-toggle-paid="${tx.id}" aria-label="Marcar ${esc(tx.description)} como ${paid?'não paga':'paga'}" aria-pressed="${paid}" ${busy?'disabled aria-busy="true"':''}>${svg(ICON.check)}</button>`:''}<span class="tx-icon category" style="--cat:${cat.color}">${cat.emoji}</span><div class="tx-copy"><strong>${esc(tx.description)}</strong><small class="tx-meta"><span>${esc(cat.label)}${card?` · ${esc(card.name)}`:''}</span><i class="payment-badge ${paid?'paid':'unpaid'}">${paid?'Pago':'Não pago'}</i></small></div><b>${money(tx.amount)}</b><button class="more-btn" data-edit-tx="${tx.id}" aria-label="Opções">•••</button></div>`}
function txList(items,label,type){return `<section class="list-card ${type}"><div class="list-head"><h2>${label}</h2><span>${items.length}</span></div>${items.length?items.map(txRow).join(''):`<div class="empty">Nenhuma ${type==='income'?'receita':'despesa'} neste mês.</div>`}</section>`}
function previousPendingBanner(){const count=state.previousPending.length;if(!count)return '';const total=state.previousPending.reduce((sum,tx)=>sum+Number(tx.amount||0),0),label=count===1?'1 despesa não paga':`${count} despesas não pagas`;return `<button class="previous-pending" data-previous-pending><span><small>Mês anterior</small><strong>Você ainda tem ${label} de ${esc(monthName(previousMonth()))} · ${money(total)}</strong></span><b>Ver pendências <i>→</i></b></button>`}
function homeView(){const s=summary();const expenses=state.transactions.filter(t=>t.direction==='expense').slice(0,5),income=state.transactions.filter(t=>t.direction==='income').slice(0,5);return `${topbar('Início')}<section class="home-intro"><h2>Seu mês até agora</h2><p>Veja entradas, saídas e o resultado do mês.</p></section>${previousPendingBanner()}<section class="balance-card"><button class="eye-btn" data-hide-values aria-label="${state.valuesHidden?'Mostrar valores':'Ocultar valores'}">${svg(ICON.eye)}</button><span class="eyebrow">Saldo do mês</span><strong class="big-balance">${moneyVisible(s.result)}</strong><small>Atualizado agora há pouco</small><div class="mini-grid"><article class="income"><span>${svg(ICON.income)}<em>Receitas</em></span><strong>${moneyVisible(s.income)}</strong></article><article class="expense"><span>${svg(ICON.expense)}<em>Despesas</em></span><strong>${moneyVisible(s.expense)}</strong></article></div></section><h3 class="section-label">Ações rápidas</h3><div class="quick-grid">${actionButton('expense','Despesa','Novo gasto','new-expense')}${actionButton('income','Receita','Nova entrada','new-income')}</div><div class="home-lists">${txList(expenses,'Despesas','expense')}${txList(income,'Receitas','income')}</div>`}
function transactionsView(){const s=summary(),allExpenses=state.transactions.filter(t=>t.direction==='expense'),expenses=state.unpaidOnly?allExpenses.filter(t=>isPayable(t)&&!t.is_paid):allExpenses,income=state.transactions.filter(t=>t.direction==='income'),focus=state.unpaidOnly?`<div class="unpaid-focus"><span>Mostrando somente despesas não pagas</span><button data-clear-unpaid aria-label="Mostrar todas as despesas">Mostrar todas</button></div>`:'';return `${topbar('Movimentações')}${monthControl()}<section class="balance-card tx-balance"><span class="eyebrow">Saldo do mês</span><strong class="big-balance">${money(s.result)}</strong><small>Receitas menos despesas do período selecionado</small><div class="mini-grid"><article class="income"><em>Receitas</em><strong>${money(s.income)}</strong></article><article class="expense"><em>Despesas</em><strong>${money(s.expense)}</strong></article></div></section><h3 class="section-label">Ações rápidas</h3><div class="quick-grid">${actionButton('expense','Despesa','Novo gasto','new-expense')}${actionButton('income','Receita','Nova entrada','new-income')}${actionButton('boxes','Caixinha','Guardar valor','box-add')}${actionButton('recurring','Gasto fixo','Nova recorrência','new-recurring')}</div>${focus}${state.monthLoading?'<div class="loading-card month-loading">Carregando movimentações…</div>':`<div class="extract-grid">${txList(expenses,state.unpaidOnly?'Despesas não pagas':'Despesas','expense')}${state.unpaidOnly?'':txList(income,'Receitas','income')}</div>`}`}
function boxesView(){return `${topbar('Caixinhas')}<div class="page-action"><button class="create-btn" data-action="new-box">+ Nova caixinha</button></div><div class="boxes-list">${state.boxes.length?state.boxes.map(b=>{const bal=balanceFor(b.id),target=Number(b.target_amount||0),pct=target?Math.max(0,Math.min(100,Math.round(bal/target*100))):0;return `<article class="box-card-v31" data-box="${b.id}"><span class="box-glyph">${svg(ICON.boxes)}</span><div class="box-title"><strong>${esc(b.name)}</strong><small>${target?`Meta ${money(target)}`:'Sem meta definida'}</small></div><button class="more-btn" data-edit-box="${b.id}" aria-label="Opções">•••</button><div class="box-balance-v31"><strong>${money(bal)}</strong><small>Saldo atual</small></div>${target?`<div class="progress-meta"><span>${pct}% da meta</span><span>${b.target_date?`Até ${esc(monthShort(b.target_date))}`:'Sem prazo'}</span></div><div class="progress"><i style="width:${pct}%"></i></div><p>${bal>=target?'Meta atingida.':`Faltam ${money(Math.max(0,target-bal))} para o objetivo.`}</p>`:''}<div class="box-actions"><button class="primary" data-box-add="${b.id}">Adicionar</button><button data-box-withdraw="${b.id}">Retirar</button><button data-box-history="${b.id}">Histórico</button></div></article>`}).join(''):'<div class="empty-card">Crie a primeira caixinha de vocês.</div>'}</div>`}
function goalsView(){const pending=state.goals.filter(g=>!g.is_completed),done=state.goals.filter(g=>g.is_completed);return `${topbar('Metas')}<div class="page-action"><button class="create-btn" data-action="new-goal">+ Nova meta</button></div><section class="goals-card"><div class="goals-head"><span>${pending.length} ${pending.length===1?'pendente':'pendentes'}</span><span>${done.length} ${done.length===1?'concluída':'concluídas'}</span></div>${state.goals.length?[...pending,...done].map(g=>`<div class="goal-row-v31 ${g.is_completed?'completed':''}"><button class="goal-check ${g.is_completed?'done':''}" data-goal-toggle="${g.id}">${g.is_completed?'✓':''}</button><div><strong>${esc(g.title)}</strong>${g.notes?`<small>${esc(g.notes)}</small>`:''}<span>${g.due_date?monthShort(g.due_date):'Sem prazo'}</span></div><button class="more-btn" data-edit-goal="${g.id}" aria-label="Opções">•••</button></div>`).join(''):'<div class="empty">Nenhuma meta ainda.</div>'}</section>`}
function addMonths(iso,n){const d=new Date(`${iso}T12:00:00`);return monthISO(new Date(d.getFullYear(),d.getMonth()+n,1))}
function reportOptions(selected){const now=currentMonth();let out='';for(let i=-36;i<=12;i++){const m=addMonths(now,i);out+=`<option value="${m}" ${m===selected?'selected':''}>${esc(monthShort(m))}</option>`}return out}
function reportMonths(){const months=[];let c=state.reportStart;while(c<=state.reportEnd&&months.length<60){months.push(c);c=addMonths(c,1)}return months}
function chartSvg(rows){const months=reportMonths(),map=new Map(rows.map(r=>[String(r.month).slice(0,10),r])),data=months.map(m=>({m,income:Number(map.get(m)?.total_income||0),expense:Number(map.get(m)?.total_expense||0)}));const W=640,H=230,L=30,R=18,T=18,B=38,max=Math.max(1,...data.flatMap(x=>[x.income,x.expense])),pw=W-L-R,ph=H-T-B,x=i=>data.length===1?L+pw/2:L+i/(data.length-1)*pw,y=v=>T+ph-(v/max)*ph,line=k=>data.map((d,i)=>`${x(i)},${y(d[k])}`).join(' ');return `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Receitas e despesas"><line x1="${L}" y1="${T+ph}" x2="${W-R}" y2="${T+ph}" class="guide"/><polyline class="line income" points="${line('income')}"/><polyline class="line expense" points="${line('expense')}"/>${data.map((d,i)=>`<circle class="dot income" cx="${x(i)}" cy="${y(d.income)}" r="3"/><circle class="dot expense" cx="${x(i)}" cy="${y(d.expense)}" r="3"/>${(data.length<=8||i%2===0||i===data.length-1)?`<text x="${x(i)}" y="${H-11}" text-anchor="middle">${esc(monthShort(d.m).split(' ')[0])}</text>`:''}`).join('')}</svg>`}
function categoryBreakdown(){const totals=new Map(REPORT_CATEGORIES.map(k=>[k,0]));for(const tx of state.reportTransactions){const key=tx.kind==='recurring'?'recurring':tx.category||'uncategorized';totals.set(key,(totals.get(key)||0)+Number(tx.amount||0))}return REPORT_CATEGORIES.map(key=>({key,...CATEGORIES[key],amount:totals.get(key)||0})).filter(x=>x.amount>.005).sort((a,b)=>b.amount-a.amount)}
function cardBreakdown(){const totals=new Map(state.cards.map(c=>[c.id,0]));for(const tx of state.reportTransactions){if(tx.card_id&&totals.has(tx.card_id))totals.set(tx.card_id,(totals.get(tx.card_id)||0)+Number(tx.amount||0))}return state.cards.map(card=>({key:card.id,label:card.name,glyph:cardGlyph(card),color:card.color,amount:totals.get(card.id)||0})).filter(x=>x.amount>.005).sort((a,b)=>b.amount-a.amount)}
function donutSvg(items,aria='Distribuição de despesas'){const total=items.reduce((s,x)=>s+x.amount,0),r=58,circ=2*Math.PI*r;let offset=0;const segments=items.map(item=>{const len=total?item.amount/total*circ:0;const out=`<circle cx="90" cy="90" r="${r}" fill="none" stroke="${item.color}" stroke-width="25" stroke-dasharray="${len} ${Math.max(0,circ-len)}" stroke-dashoffset="${-offset}" transform="rotate(-90 90 90)"/>`;offset+=len;return out}).join('');return `<div class="category-donut"><svg viewBox="0 0 180 180" role="img" aria-label="${esc(aria)}"><circle cx="90" cy="90" r="${r}" fill="none" class="donut-track" stroke-width="25"/>${segments}</svg><div class="donut-center"><span>Total</span><strong>${money(total)}</strong></div></div>`}
function categoryBarsSvg(){const months=reportMonths(),selected=state.reportCategory,cat=selected==='all'?null:CATEGORIES[selected],data=months.map(m=>({m,amount:state.reportTransactions.filter(t=>String(t.month).slice(0,10)===m&&(selected==='all'||(t.kind==='recurring'?'recurring':t.category||'uncategorized')===selected)).reduce((s,t)=>s+Number(t.amount||0),0)}));const W=640,H=245,L=28,R=12,T=18,B=40,max=Math.max(1,...data.map(d=>d.amount)),pw=W-L-R,ph=H-T-B,slot=pw/Math.max(1,data.length),bw=Math.min(42,slot*.58),y=v=>T+ph-(v/max)*ph,color=cat?.color||'#7C5CE6';return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Despesas por mês"><line x1="${L}" y1="${T+ph}" x2="${W-R}" y2="${T+ph}" class="guide"/>${data.map((d,i)=>{const x=L+i*slot+(slot-bw)/2,h=Math.max(0,T+ph-y(d.amount));return `<rect x="${x}" y="${y(d.amount)}" width="${bw}" height="${h}" rx="6" fill="${color}" opacity="${d.amount?'.88':'.16'}"/><text x="${x+bw/2}" y="${H-11}" text-anchor="middle">${esc(monthShort(d.m).split(' ')[0])}</text>`}).join('')}</svg>`}
function legendRows(items,total,glyphKey='emoji'){return `<div class="category-legend">${items.map(item=>`<div class="category-legend-row"><span class="legend-dot" style="--cat:${item.color}">${item[glyphKey]||'•'}</span><div><strong>${esc(item.label)}</strong><small>${total?Math.round(item.amount/total*100):0}%</small></div><b>${money(item.amount)}</b></div>`).join('')}</div>`}
function reportsView(){const income=state.reportRows.reduce((s,r)=>s+Number(r.total_income||0),0),expense=state.reportRows.reduce((s,r)=>s+Number(r.total_expense||0),0),breakdown=categoryBreakdown(),totalCat=breakdown.reduce((s,x)=>s+x.amount,0),cards=cardBreakdown(),totalCards=cards.reduce((s,x)=>s+x.amount,0),filterLabel=state.reportCategory==='all'?'Todas as categorias':CATEGORIES[state.reportCategory]?.label||'Categoria';return `${topbar('Relatórios')}<section class="period-card"><span>Período</span><div><label>De<select data-report-start>${reportOptions(state.reportStart)}</select></label><b>→</b><label>Até<select data-report-end>${reportOptions(state.reportEnd)}</select></label></div><div class="period-presets"><button data-preset="month">Este mês</button><button data-preset="3">3 meses</button><button data-preset="6">6 meses</button><button data-preset="year">Este ano</button></div></section>${state.reportLoading?'<div class="loading-card">Carregando relatório…</div>':`<section class="balance-card report-balance"><span class="eyebrow">Saldo no período</span><strong class="big-balance">${money(income-expense)}</strong><small>${monthShort(state.reportStart)} até ${monthShort(state.reportEnd)}</small><div class="mini-grid"><article class="income"><em>Receitas</em><strong>${money(income)}</strong></article><article class="expense"><em>Despesas</em><strong>${money(expense)}</strong></article></div></section><section class="category-report-card"><div class="report-card-head"><div><h2>Despesas por categoria</h2><p>Veja onde o dinheiro saiu no período.</p></div></div>${breakdown.length?`<div class="category-donut-layout">${donutSvg(breakdown,'Despesas por categoria')}${legendRows(breakdown,totalCat)}</div>`:'<div class="empty">Sem despesas no período selecionado.</div>'}</section><section class="category-report-card"><div class="report-card-head"><div><h2>Gastos por cartão</h2><p>Somente despesas vinculadas a cartão no período.</p></div></div>${cards.length?`<div class="category-donut-layout">${donutSvg(cards,'Gastos por cartão')}${legendRows(cards,totalCards,'glyph')}</div>`:'<div class="empty">Nenhuma despesa vinculada a cartão neste período.</div>'}</section><section class="category-report-card"><div class="report-card-head"><div><h2>Evolução por categoria</h2><p>${esc(filterLabel)} · comparação mês a mês.</p></div></div><div class="category-filter"><button class="${state.reportCategory==='all'?'active':''}" data-category-filter="all">Todas</button>${REPORT_CATEGORIES.map(key=>{const c=CATEGORIES[key];return `<button class="${state.reportCategory===key?'active':''}" data-category-filter="${key}" style="--cat:${c.color}"><span>${c.emoji}</span>${esc(c.label)}</button>`}).join('')}</div><div class="category-bars">${categoryBarsSvg()}</div></section><section class="chart-card"><div><h2>Receitas x despesas</h2><p>Evolução geral mês a mês.</p></div><div class="legend"><span class="income">Receitas</span><span class="expense">Despesas</span></div><div class="chart-wrap">${chartSvg(state.reportRows)}</div></section>`}`}
function renderSplash(){app.innerHTML='<div class="splash"><div class="brand-name"><span>Ju</span>Helo</div></div>'}
function renderAuth(signup=false){app.innerHTML=`<main class="auth-page"><div class="auth-brand"><span>♡</span><strong><i>Ju</i>Helo</strong></div><section class="auth-card"><h1>${signup?'Criar sua conta':'Entrar no JuHelo'}</h1><p>${signup?'Crie sua conta e conecte o JuHelo do casal.':'Suas finanças do casal em um lugar simples.'}</p><form id="auth-form">${signup?'<label>Seu nome<input name="name" autocomplete="name" required></label>':''}<label>E-mail<input name="email" type="email" autocomplete="email" required></label><label>Senha<input name="password" type="password" minlength="6" autocomplete="current-password" required></label><button class="primary-btn">${signup?'Criar conta':'Entrar'}</button></form><button class="auth-switch" data-auth-switch>${signup?'Já tenho uma conta':'Criar uma conta'}</button></section></main>`;app.querySelector('[data-auth-switch]').onclick=()=>renderAuth(!signup);app.querySelector('#auth-form').onsubmit=async e=>{e.preventDefault();const btn=e.currentTarget.querySelector('button'),fd=new FormData(e.currentTarget);setBusy(btn,true,signup?'Criando…':'Entrando…');try{if(signup){const{error}=await db.auth.signUp({email:String(fd.get('email')).trim(),password:fd.get('password'),options:{data:{display_name:String(fd.get('name')).trim()}}});if(error)throw error;toast('Conta criada. Confira seu e-mail se necessário.')}else{const{error}=await db.auth.signInWithPassword({email:String(fd.get('email')).trim(),password:fd.get('password')});if(error)throw error}}catch(err){safeError(err,'Falha na autenticação.');setBusy(btn,false)}}}
function renderOnboarding(){app.innerHTML=`<main class="auth-page"><div class="auth-brand"><span>♡</span><strong><i>Ju</i>Helo</strong></div><section class="auth-card"><h1>Nosso dinheiro</h1><p>Crie o espaço financeiro do casal ou entre com o código da outra pessoa.</p><button class="primary-btn" data-create-household>Criar nosso JuHelo</button><div class="or">ou</div><label>Código do casal<input id="invite-code" maxlength="20" placeholder="Ex.: A1B2C3D4"></label><button class="secondary-btn" data-join-household>Entrar com código</button><button class="ghost-btn" data-logout>Sair</button></section></main>`;app.querySelector('[data-create-household]').onclick=async e=>{setBusy(e.currentTarget,true,'Criando…');const{error}=await db.rpc('create_household',{p_name:'JuHelo'});if(error){safeError(error);return setBusy(e.currentTarget,false)}await boot();toast('JuHelo criado 💜')};app.querySelector('[data-join-household]').onclick=async e=>{const code=app.querySelector('#invite-code').value.trim();if(!code)return toast('Digite o código.','error');setBusy(e.currentTarget,true,'Entrando…');const{error}=await db.rpc('join_household',{p_invite_code:code});if(error){safeError(error);return setBusy(e.currentTarget,false)}await boot();toast('Contas conectadas 💜')};app.querySelector('[data-logout]').onclick=()=>db.auth.signOut()}
function render(){if(state.loading)return renderSplash();if(!state.session)return renderAuth(false);if(!state.household)return renderOnboarding();let body=state.tab==='home'?homeView():state.tab==='transactions'?transactionsView():state.tab==='boxes'?boxesView():state.tab==='reports'?reportsView():goalsView();app.innerHTML=`<main class="page">${body}</main>${nav()}`;bind()}
function modal(title,body){const wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<section class="modal-card" role="dialog" aria-modal="true"><div class="modal-head"><h2>${esc(title)}</h2><button class="close-btn" data-close>×</button></div>${body}</section>`;document.body.appendChild(wrap);const close=()=>wrap.remove();wrap.querySelector('[data-close]').onclick=close;wrap.addEventListener('click',e=>{if(e.target===wrap)close()});return wrap}
async function toggleTransactionPaid(id){const tx=state.transactions.find(item=>item.id===id);if(!isPayable(tx)||state.paymentBusy.has(id))return;const before={is_paid:tx.is_paid,paid_at:tx.paid_at,paid_by:tx.paid_by,updated_at:tx.updated_at},next=!tx.is_paid;state.paymentBusy.add(id);tx.is_paid=next;tx.paid_at=next?new Date().toISOString():null;tx.paid_by=next?state.session.user.id:null;syncPreviousPending(tx);render();try{const{data,error}=await db.rpc('set_transaction_paid',{p_transaction_id:tx.id,p_paid:next});if(error)throw error;const saved=Array.isArray(data)?data[0]:data;if(saved&&String(saved.month).slice(0,10)===state.txMonth)upsertTx(saved);syncPreviousPending(saved||tx);toast(next?'Despesa marcada como paga.':'Despesa marcada como não paga.')}catch(error){Object.assign(tx,before);syncPreviousPending(tx);safeError(error,'Não foi possível atualizar o pagamento.')}finally{state.paymentBusy.delete(id);render()}}
async function selectTransactionMonth(month,{unpaidOnly=false}={}){const request=++state.monthRequest;state.txMonth=month;state.unpaidOnly=unpaidOnly;state.monthLoading=true;state.transactions=[];render();await syncMonth(false);if(request!==state.monthRequest)return;state.monthLoading=false;render()}
async function openPreviousPending(){state.tab='transactions';await selectTransactionMonth(previousMonth(),{unpaidOnly:true});requestAnimationFrame(()=>document.querySelector('.extract-grid')?.scrollIntoView({behavior:'smooth',block:'start'}))}
function openRecurringActions(tx){const w=modal('Gasto fixo',`<div class="transaction-actions"><div class="transaction-actions-summary"><span class="tx-icon category" style="--cat:${CATEGORIES.recurring.color}">${CATEGORIES.recurring.emoji}</span><div><strong>${esc(tx.description)}</strong><small>${money(tx.amount)} · ${esc(monthText(tx.month))}</small></div></div><button class="action-row" data-recurring-edit><span>Editar gasto fixo</span><i>→</i></button><button class="action-row danger" data-recurring-delete><span>Excluir gasto fixo</span><i>→</i></button><button class="ghost-btn" data-cancel>Cancelar</button></div>`);w.querySelector('[data-cancel]').onclick=()=>w.remove();w.querySelector('[data-recurring-edit]').onclick=()=>{w.remove();openRecurring(tx)};w.querySelector('[data-recurring-delete]').onclick=()=>{w.remove();openRecurringDelete(tx)}}
function openRecurringDelete(tx){const w=modal('Excluir gasto fixo',`<div class="recurring-delete"><p>Escolha até onde remover <strong>${esc(tx.description)}</strong>. Esta ação não altera os outros lançamentos.</p><div class="recurring-delete-options"><button data-delete-recurring-scope="this_month"><strong>Somente este mês</strong><small>Remove apenas ${esc(monthName(tx.month))}.</small></button><button data-delete-recurring-scope="future"><strong>Deste mês em diante</strong><small>Encerra o gasto fixo no mês anterior.</small></button><button class="destructive" data-delete-recurring-scope="all"><strong>Toda a série</strong><small>Remove todas as ocorrências deste gasto fixo.</small></button></div><button class="ghost-btn" data-cancel>Cancelar</button></div>`);w.querySelector('[data-cancel]').onclick=()=>w.remove();w.querySelectorAll('[data-delete-recurring-scope]').forEach(btn=>btn.onclick=async()=>{const scope=btn.dataset.deleteRecurringScope,buttons=[...w.querySelectorAll('button')],oldHtml=btn.innerHTML;buttons.forEach(button=>button.disabled=true);setBusy(btn,true,'Excluindo…');try{const{error}=await db.rpc('delete_recurring_expense',{p_transaction_id:tx.id,p_scope:scope});if(error)throw error;state.transactions=state.transactions.filter(item=>item.id!==tx.id);state.previousPending=state.previousPending.filter(item=>item.id!==tx.id);state.reportRows=[];state.reportTransactions=[];w.remove();render();toast(scope==='this_month'?'Gasto removido deste mês.':scope==='future'?'Gasto fixo encerrado a partir deste mês.':'Série do gasto fixo excluída.');try{await Promise.all([loadTransactions(state.txMonth),loadPreviousPending()]);render()}catch(err){safeError(err,'A exclusão foi concluída, mas a tela não pôde ser atualizada.')}}catch(error){buttons.forEach(button=>button.disabled=false);setBusy(btn,false);btn.innerHTML=oldHtml;safeError(error,'Não foi possível excluir o gasto fixo.')}})}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function moneyField(label,name,value=''){return `<label class="field">${label}<input name="${name}" inputmode="decimal" value="${value!==''?esc(String(value).replace('.',',')):''}" placeholder="0,00" required></label>`}
function openTransaction(tx=null,preset='expense'){let direction=tx?.direction||preset;let category=direction==='expense'&&USER_EXPENSE_CATEGORIES.includes(tx?.category)?tx.category:'';let cardId=direction==='expense'?(tx?.card_id||''):'';const w=modal(tx?'Editar lançamento':direction==='income'?'Nova receita':'Nova despesa',`<form class="form-grid" data-tx-form><div class="segmented"><button type="button" data-dir="expense" class="${direction==='expense'?'active':''}">Despesa</button><button type="button" data-dir="income" class="${direction==='income'?'active':''}">Receita</button></div>${field('Descrição','description',tx?.description||'','text','maxlength="160" required')}${moneyField('Valor','amount',tx?.amount||'')}<div data-expense-details>${cardSelect(cardId)}<div data-category-wrap>${categoryOptions(category)}</div></div><label class="field">Mês<select name="month">${monthOptions(tx?.month||state.txMonth)}</select></label>${tx?'<button class="danger-btn" type="button" data-delete>Excluir lançamento</button>':''}<div class="modal-actions"><button type="button" class="ghost-btn" data-cancel>Cancelar</button><button class="primary-btn" type="submit">Salvar</button></div></form>`);const syncExpenseUI=()=>{const details=w.querySelector('[data-expense-details]');if(details)details.hidden=direction!=='expense';const card=cardFor(cardId);const hint=w.querySelector('[data-card-hint]');if(hint)hint.textContent=cardUseText(card);w.querySelectorAll('[data-category]').forEach(b=>{b.classList.toggle('is-selected',b.dataset.category===category);b.classList.toggle('is-recommended',!!card&&(card.allowed_categories||[]).includes(b.dataset.category))});const sel=w.querySelector('[data-card-select]');if(sel&&sel.value!==cardId)sel.value=cardId};w.querySelector('[data-cancel]').onclick=()=>w.remove();w.querySelectorAll('[data-dir]').forEach(b=>b.onclick=()=>{direction=b.dataset.dir;w.querySelectorAll('[data-dir]').forEach(x=>x.classList.toggle('active',x===b));syncExpenseUI()});w.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;if(category==='debit_pix')cardId='';else if(!cardId){const preferred=preferredCardForCategory(category);if(preferred)cardId=preferred.id}syncExpenseUI()});w.querySelector('[data-card-select]')?.addEventListener('change',e=>{cardId=e.target.value;const card=cardFor(cardId),allowed=card?.allowed_categories||[];if(allowed.length===1&&USER_EXPENSE_CATEGORIES.includes(allowed[0]))category=allowed[0];syncExpenseUI()});syncExpenseUI();w.querySelector('[data-delete]')?.addEventListener('click',async()=>{if(!confirm('Excluir este lançamento?'))return;const{error}=await db.from('transactions').delete().eq('id',tx.id);if(error)return safeError(error);state.transactions=state.transactions.filter(x=>x.id!==tx.id);w.remove();render();toast('Lançamento excluído.');syncMonth(false)});w.querySelector('[data-tx-form]').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,btn=form.querySelector('[type="submit"]'),fd=new FormData(form),amount=parseMoney(fd.get('amount'));if(!amount||amount<=0)return toast('Digite um valor válido.','error');if(direction==='expense'&&!category)return toast('Escolha uma categoria.','error');if(category==='debit_pix')cardId='';const payload={household_id:householdId(),direction,kind:tx?.kind||'regular',description:String(fd.get('description')).trim(),amount,month:fd.get('month'),category:direction==='expense'?category:null,card_id:direction==='expense'?(cardId||null):null,updated_by:state.session.user.id};setBusy(btn,true);try{let data,error;if(tx)({data,error}=await db.from('transactions').update(payload).eq('id',tx.id).select().single());else({data,error}=await db.from('transactions').insert({...payload,created_by:state.session.user.id}).select().single());if(error)throw error;if(String(data.month).slice(0,10)===state.txMonth)upsertTx(data);else if(tx)state.transactions=state.transactions.filter(x=>x.id!==tx.id);w.remove();render();toast(tx?'Lançamento atualizado.':'Lançamento salvo.');syncMonth(false).then(()=>render())}catch(err){safeError(err,'Não foi possível salvar o lançamento.');setBusy(btn,false)}}}
function openRecurring(tx=null){const editing=!!tx,defaultCard=tx?.card_id||preferredCardForCategory('recurring')?.id||cardBySlug('santander_julio')?.id||'';const w=modal(editing?'Editar gasto fixo':'Novo gasto fixo',`<form class="form-grid" data-rec-form>${categoryReadonly('recurring')}${field('Descrição','description',tx?.description||'','text','required')}${moneyField('Valor','amount',tx?.amount||'')}${cardSelect(defaultCard,'Cartão do gasto fixo')}${editing?`<label class="field">Aplicar alteração<select name="scope"><option value="this_month">Somente este mês</option><option value="future">Deste mês em diante</option><option value="all">Toda a série</option></select></label>`:`<label class="field">Começa em<select name="start">${monthOptions(state.txMonth)}</select></label><label class="field">Vai até <span>opcional</span><select name="end"><option value="">Sem mês final</option>${monthOptions(state.txMonth,36)}</select></label>`}<div class="modal-actions"><button type="button" class="ghost-btn" data-cancel>Cancelar</button><button class="primary-btn">${editing?'Salvar':'Criar gasto fixo'}</button></div></form>`);const updateHint=()=>{const sel=w.querySelector('[data-card-select]'),hint=w.querySelector('[data-card-hint]');if(hint)hint.textContent=cardUseText(cardFor(sel?.value))};w.querySelector('[data-card-select]')?.addEventListener('change',updateHint);updateHint();w.querySelector('[data-cancel]').onclick=()=>w.remove();w.querySelector('[data-rec-form]').onsubmit=async e=>{e.preventDefault();const btn=e.currentTarget.querySelector('.primary-btn'),fd=new FormData(e.currentTarget),amount=parseMoney(fd.get('amount')),cardId=fd.get('card_id')||defaultCard||null;if(!amount||amount<=0)return toast('Digite um valor válido.','error');setBusy(btn,true);try{let error;if(editing)({error}=await db.rpc('edit_recurring_expense',{p_transaction_id:tx.id,p_scope:fd.get('scope'),p_description:String(fd.get('description')).trim(),p_amount:amount,p_card_id:cardId}));else{const end=fd.get('end');if(end&&end<fd.get('start'))throw new Error('O mês final não pode ser anterior ao inicial.');({error}=await db.rpc('create_recurring_expense',{p_household_id:householdId(),p_description:String(fd.get('description')).trim(),p_amount:amount,p_start_month:fd.get('start'),p_end_month:end||null,p_card_id:cardId}))}if(error)throw error;w.remove();toast(editing?'Gasto fixo atualizado.':'Gasto fixo criado.');await syncMonth(true)}catch(err){safeError(err);setBusy(btn,false)}}}
function openBoxEditor(box=null){const w=modal(box?'Editar caixinha':'Nova caixinha',`<form class="form-grid" data-box-form>${field('Nome','name',box?.name||'','text','required maxlength="100"')}<label class="field">Meta de valor <span>opcional</span><input name="target" inputmode="decimal" value="${box?.target_amount?esc(String(box.target_amount).replace('.',',')):''}" placeholder="0,00"></label><label class="field">Prazo <span>opcional</span><select name="target_date"><option value="">Sem prazo</option>${monthOptions(box?.target_date||state.txMonth,60)}</select></label>${box?'<button type="button" class="ghost-btn" data-archive>Arquivar caixinha</button>':''}<div class="modal-actions"><button type="button" class="ghost-btn" data-cancel>Cancelar</button><button class="primary-btn">Salvar</button></div></form>`);w.querySelector('[data-cancel]').onclick=()=>w.remove();w.querySelector('[data-archive]')?.addEventListener('click',async()=>{if(Math.abs(balanceFor(box.id))>.005)return toast('Zere o saldo antes de arquivar.','error');const{error}=await db.from('boxes').update({is_archived:true}).eq('id',box.id);if(error)return safeError(error);w.remove();await loadBoxes();render();toast('Caixinha arquivada.')});w.querySelector('[data-box-form]').onsubmit=async e=>{e.preventDefault();const btn=e.currentTarget.querySelector('.primary-btn'),fd=new FormData(e.currentTarget),target=fd.get('target')?parseMoney(fd.get('target')):null,payload={name:String(fd.get('name')).trim(),target_amount:Number.isFinite(target)?target:null,target_date:fd.get('target_date')||null};setBusy(btn,true);try{let error;if(box)({error}=await db.from('boxes').update(payload).eq('id',box.id));else({error}=await db.from('boxes').insert({...payload,household_id:householdId(),created_by:state.session.user.id}));if(error)throw error;w.remove();await loadBoxes();render();toast(box?'Caixinha atualizada.':'Caixinha criada.')}catch(err){safeError(err);setBusy(btn,false)}}}
function openBoxAdd(boxId=''){if(!state.boxes.length)return toast('Crie uma caixinha primeiro.','error');const w=modal('Adicionar à caixinha',`<form class="form-grid" data-add-box>${categoryReadonly('box')}<label class="field">Caixinha<select name="box">${state.boxes.map(b=>`<option value="${b.id}" ${b.id===boxId?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label>${moneyField('Valor','amount')}<label class="field">Mês<select name="month">${monthOptions(state.txMonth)}</select></label>${field('Descrição (opcional)','description','','text','maxlength="160"')}<div class="modal-actions"><button type="button" class="ghost-btn" data-cancel>Cancelar</button><button class="primary-btn">Adicionar</button></div></form>`);w.querySelector('[data-cancel]').onclick=()=>w.remove();w.querySelector('[data-add-box]').onsubmit=async e=>{e.preventDefault();const btn=e.currentTarget.querySelector('.primary-btn'),fd=new FormData(e.currentTarget),amount=parseMoney(fd.get('amount'));if(!amount||amount<=0)return toast('Digite um valor válido.','error');setBusy(btn,true,'Adicionando…');try{const{error}=await db.rpc('add_box_contribution',{p_box_id:fd.get('box'),p_amount:amount,p_month:fd.get('month'),p_description:String(fd.get('description')).trim()||null});if(error)throw error;w.remove();toast('Valor guardado na caixinha.');await Promise.all([loadBoxes(),loadTransactions(state.txMonth)]);render()}catch(err){safeError(err);setBusy(btn,false)}}}
function openWithdraw(box){const bal=balanceFor(box.id),w=modal('Retirar da caixinha',`<form class="form-grid" data-withdraw><div class="balance-note">Saldo disponível: <strong>${money(bal)}</strong></div>${moneyField('Valor','amount')}<label class="field">Mês<select name="month">${monthOptions(state.txMonth)}</select></label>${field('Descrição (opcional)','description')}<div class="modal-actions"><button type="button" class="ghost-btn" data-cancel>Cancelar</button><button class="primary-btn">Retirar</button></div></form>`);w.querySelector('[data-cancel]').onclick=()=>w.remove();w.querySelector('[data-withdraw]').onsubmit=async e=>{e.preventDefault();const btn=e.currentTarget.querySelector('.primary-btn'),fd=new FormData(e.currentTarget),amount=parseMoney(fd.get('amount'));if(!amount||amount<=0)return toast('Digite um valor válido.','error');if(amount>bal)return toast('Saldo insuficiente.','error');setBusy(btn,true,'Retirando…');try{const{error}=await db.rpc('withdraw_from_box',{p_box_id:box.id,p_amount:amount,p_month:fd.get('month'),p_description:String(fd.get('description')).trim()||null});if(error)throw error;w.remove();toast('Retirada registrada.');await loadBoxes();render()}catch(err){safeError(err);setBusy(btn,false)}}}
async function openBoxHistory(box){const w=modal(`Histórico · ${box.name}`,'<div class="loading-card">Carregando histórico…</div>');const{data,error}=await db.from('box_movements').select('movement_type,amount,month,description,created_at').eq('household_id',householdId()).eq('box_id',box.id).order('created_at',{ascending:false}).limit(100);if(error){w.querySelector('.modal-card').insertAdjacentHTML('beforeend','<div class="empty">Não foi possível carregar.</div>');return}const body=w.querySelector('.loading-card');body.outerHTML=`<div class="history-balance"><span>Saldo atual</span><strong>${money(balanceFor(box.id))}</strong></div><div class="history-list">${data?.length?data.map(m=>`<div class="history-row"><div><strong>${esc(m.description||(m.movement_type==='withdrawal'?'Retirada':'Depósito'))}</strong><small>${monthShort(m.month)}</small></div><b class="${m.movement_type==='withdrawal'?'negative':'positive'}">${m.movement_type==='withdrawal'?'−':'+'}${money(m.amount)}</b></div>`).join(''):'<div class="empty">Nenhuma movimentação ainda.</div>'}</div>`}
function openGoal(goal=null){const w=modal(goal?'Editar meta':'Nova meta',`<form class="form-grid" data-goal-form>${field('Meta','title',goal?.title||'','text','required maxlength="120"')}${field('Observação (opcional)','notes',goal?.notes||'','text','maxlength="400"')}<label class="field">Prazo <span>opcional</span><select name="due_date"><option value="">Sem prazo</option>${monthOptions(goal?.due_date||state.txMonth,60)}</select></label>${goal?'<button type="button" class="danger-btn" data-delete>Excluir meta</button>':''}<div class="modal-actions"><button type="button" class="ghost-btn" data-cancel>Cancelar</button><button class="primary-btn">Salvar</button></div></form>`);w.querySelector('[data-cancel]').onclick=()=>w.remove();w.querySelector('[data-delete]')?.addEventListener('click',async()=>{if(!confirm('Excluir esta meta?'))return;const{error}=await db.from('goals').delete().eq('id',goal.id);if(error)return safeError(error);state.goals=state.goals.filter(g=>g.id!==goal.id);w.remove();render();toast('Meta excluída.')});w.querySelector('[data-goal-form]').onsubmit=async e=>{e.preventDefault();const btn=e.currentTarget.querySelector('.primary-btn'),fd=new FormData(e.currentTarget),payload={title:String(fd.get('title')).trim(),notes:String(fd.get('notes')).trim()||null,due_date:fd.get('due_date')||null,box_id:null,target_amount:null,auto_complete:false};setBusy(btn,true);try{let data,error;if(goal)({data,error}=await db.from('goals').update(payload).eq('id',goal.id).select().single());else({data,error}=await db.from('goals').insert({...payload,household_id:householdId(),created_by:state.session.user.id}).select().single());if(error)throw error;const idx=state.goals.findIndex(g=>g.id===data.id);if(idx>=0)state.goals[idx]=data;else state.goals.push(data);w.remove();render();toast(goal?'Meta atualizada.':'Meta criada.')}catch(err){safeError(err);setBusy(btn,false)}}}
function cardSettingsMarkup(){return `<form data-cards-form class="card-settings-form"><div class="card-settings-list">${state.cards.map(card=>`<article class="card-setting" data-card-setting="${card.id}" style="--card:${card.color}"><div class="card-setting-head"><span>${cardGlyph(card)}</span><div><strong>${esc(card.name)}</strong><small>${esc(card.bank)} · ${esc(card.owner_label)}</small></div></div><div class="card-purpose-grid">${CARD_PURPOSE_CATEGORIES.map(key=>{const c=CATEGORIES[key],active=(card.allowed_categories||[]).includes(key);return `<button type="button" class="card-purpose ${active?'selected':''}" data-card-purpose="${key}" style="--cat:${c.color}"><span>${c.emoji}</span>${esc(c.label)}<i>${active?'✓':''}</i></button>`}).join('')}</div></article>`).join('')}</div><button class="primary-btn" type="submit">Salvar cartões</button></form>`}
function openSettings(){const pref=localStorage.getItem('juhelo-theme-preference')||'light',w=document.createElement('div');w.className='settings-overlay';w.innerHTML=`<section class="settings-panel"><div class="settings-head"><div><span class="settings-avatar">${esc(initials(displayName()))}</span><div><h2>Ajustes</h2><p>${esc(state.session.user.email||'')}</p></div></div><button class="close-btn" data-close>×</button></div><nav class="settings-tabs"><button class="active" data-stab="profile">Perfil</button><button data-stab="couple">Casal</button><button data-stab="cards">Cartões</button><button data-stab="security">Segurança</button><button data-stab="theme">Tema</button></nav><div class="settings-content"><section class="settings-section active" data-ssection="profile"><h3>Seu perfil</h3><p>Como sua conta aparece dentro do JuHelo.</p><form data-profile-form class="form-grid">${field('Nome','display_name',displayName(),'text','required')}<button class="primary-btn">Salvar nome</button></form></section><section class="settings-section" data-ssection="couple"><h3>Contas conectadas</h3><p>${state.members.length===2?'O casal está conectado.':'Compartilhe o código para conectar a segunda pessoa.'}</p><div class="members-settings">${state.members.map(m=>`<div><span>${esc(initials(m.profile?.display_name||'JH'))}</span><div><strong>${esc(m.profile?.display_name||'Pessoa')}</strong><small>${m.user_id===state.session.user.id?'Você':m.role==='owner'?'Criou o JuHelo':'Parceiro(a)'}</small></div></div>`).join('')}</div><div class="invite-card"><span>Código do casal</span><strong>${esc(state.household.invite_code||'')}</strong><button class="secondary-btn" data-copy>Copiar código</button></div></section><section class="settings-section" data-ssection="cards"><h3>Cartões e categorias</h3><p>Defina para quais tipos de gasto cada cartão é planejado. Isso sugere o cartão ao lançar uma despesa e pode ser alterado sem reescrever seu histórico.</p>${cardSettingsMarkup()}</section><section class="settings-section" data-ssection="security"><h3>Segurança</h3><form data-password-form class="form-grid">${field('Nova senha','password','','password','minlength="8" required')}${field('Confirmar senha','confirm','','password','minlength="8" required')}<button class="primary-btn">Atualizar senha</button></form><button class="danger-btn" data-logout>Sair deste dispositivo</button></section><section class="settings-section" data-ssection="theme"><h3>Aparência</h3><p>Escolha como o JuHelo aparece neste aparelho.</p><div class="theme-options">${[['light','Claro','Visual claro e suave','sun'],['dark','Escuro','Confortável em ambientes escuros','moon'],['system','Sistema','Segue o tema do aparelho','system']].map(([id,n,d,ic])=>`<button class="theme-option ${pref===id?'selected':''}" data-theme="${id}"><span>${svg(ICON[ic])}</span><div><strong>${n}</strong><small>${d}</small></div><i>${pref===id?'✓':''}</i></button>`).join('')}</div></section></div></section>`;document.body.appendChild(w);const close=()=>w.remove();w.querySelector('[data-close]').onclick=close;w.addEventListener('click',e=>{if(e.target===w)close()});w.querySelectorAll('[data-stab]').forEach(b=>b.onclick=()=>{w.querySelectorAll('[data-stab]').forEach(x=>x.classList.toggle('active',x===b));w.querySelectorAll('[data-ssection]').forEach(s=>s.classList.toggle('active',s.dataset.ssection===b.dataset.stab))});w.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{applyTheme(b.dataset.theme);w.querySelectorAll('[data-theme]').forEach(x=>{x.classList.toggle('selected',x===b);x.querySelector('i').textContent=x===b?'✓':''})});w.querySelectorAll('[data-card-purpose]').forEach(b=>b.onclick=()=>{b.classList.toggle('selected');b.querySelector('i').textContent=b.classList.contains('selected')?'✓':''});w.querySelector('[data-cards-form]')?.addEventListener('submit',async e=>{e.preventDefault();const btn=e.currentTarget.querySelector('.primary-btn'),settings=[...e.currentTarget.querySelectorAll('[data-card-setting]')];setBusy(btn,true);try{await Promise.all(settings.map(async node=>{const id=node.dataset.cardSetting,categories=[...node.querySelectorAll('[data-card-purpose].selected')].map(x=>x.dataset.cardPurpose),{error}=await db.from('payment_cards').update({allowed_categories:categories,updated_at:new Date().toISOString()}).eq('id',id);if(error)throw error;const card=cardFor(id);if(card)card.allowed_categories=categories}));toast('Preferências dos cartões salvas.');setBusy(btn,false)}catch(err){safeError(err,'Não foi possível salvar os cartões.');setBusy(btn,false)}});w.querySelector('[data-copy]').onclick=async()=>{try{await navigator.clipboard.writeText(state.household.invite_code);toast('Código copiado.')}catch{toast(`Código: ${state.household.invite_code}`)}};w.querySelector('[data-profile-form]').onsubmit=async e=>{e.preventDefault();const btn=e.currentTarget.querySelector('button'),name=String(new FormData(e.currentTarget).get('display_name')).trim();if(name.length<2)return toast('Digite um nome válido.','error');setBusy(btn,true);const[{error:pe},{error:ae}]=await Promise.all([db.from('profiles').update({display_name:name}).eq('id',state.session.user.id),db.auth.updateUser({data:{display_name:name}})]);if(pe||ae){safeError(pe||ae);return setBusy(btn,false)}state.profile={...(state.profile||{}),display_name:name};toast('Nome atualizado.');close();render()};w.querySelector('[data-password-form]').onsubmit=async e=>{e.preventDefault();const btn=e.currentTarget.querySelector('button'),fd=new FormData(e.currentTarget);if(fd.get('password')!==fd.get('confirm'))return toast('As senhas não coincidem.','error');setBusy(btn,true,'Atualizando…');const{error}=await db.auth.updateUser({password:fd.get('password')});if(error){safeError(error);return setBusy(btn,false)}toast('Senha atualizada.');e.currentTarget.reset();setBusy(btn,false)};w.querySelector('[data-logout]').onclick=()=>db.auth.signOut()}
async function switchTab(tab){const oldTab=state.tab;state.tab=tab;if(tab==='home'){state.unpaidOnly=false;if(state.txMonth!==currentMonth())await selectTransactionMonth(currentMonth());else{try{await loadPreviousPending()}catch(e){safeError(e,'Não foi possível verificar as pendências do mês anterior.')}render()}}else if(tab==='transactions'){if(oldTab!=='transactions')state.unpaidOnly=false;render()}else if(tab==='boxes'){try{await loadBoxes()}catch(e){safeError(e)}render()}else if(tab==='goals'){try{await loadGoals()}catch(e){safeError(e)}render()}else if(tab==='reports'){render();if(!state.reportRows.length)loadReport()}}
function bind(){app.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));app.querySelectorAll('[data-settings-open]').forEach(b=>b.onclick=openSettings);app.querySelector('[data-hide-values]')?.addEventListener('click',()=>{state.valuesHidden=!state.valuesHidden;render()});app.querySelector('[data-previous-pending]')?.addEventListener('click',openPreviousPending);app.querySelector('[data-clear-unpaid]')?.addEventListener('click',()=>{state.unpaidOnly=false;render()});app.querySelectorAll('[data-toggle-paid]').forEach(b=>b.onclick=()=>toggleTransactionPaid(b.dataset.togglePaid));const ms=app.querySelector('#month-select');if(ms)ms.onchange=()=>selectTransactionMonth(ms.value);app.querySelectorAll('[data-action="new-expense"]').forEach(b=>b.onclick=()=>openTransaction(null,'expense'));app.querySelectorAll('[data-action="new-income"]').forEach(b=>b.onclick=()=>openTransaction(null,'income'));app.querySelectorAll('[data-action="new-recurring"]').forEach(b=>b.onclick=()=>openRecurring());app.querySelectorAll('[data-action="box-add"]').forEach(b=>b.onclick=()=>openBoxAdd());app.querySelectorAll('[data-action="new-box"]').forEach(b=>b.onclick=()=>openBoxEditor());app.querySelectorAll('[data-action="new-goal"]').forEach(b=>b.onclick=()=>openGoal());app.querySelectorAll('[data-edit-tx]').forEach(b=>b.onclick=()=>{const tx=state.transactions.find(t=>t.id===b.dataset.editTx);if(!tx)return;if(tx.kind==='recurring')return openRecurringActions(tx);if(tx.kind==='box_contribution')return toast('Aportes são gerenciados pela aba Caixinhas.');openTransaction(tx)});app.querySelectorAll('[data-edit-box]').forEach(b=>b.onclick=()=>openBoxEditor(state.boxes.find(x=>x.id===b.dataset.editBox)));app.querySelectorAll('[data-box-add]').forEach(b=>b.onclick=()=>openBoxAdd(b.dataset.boxAdd));app.querySelectorAll('[data-box-withdraw]').forEach(b=>b.onclick=()=>openWithdraw(state.boxes.find(x=>x.id===b.dataset.boxWithdraw)));app.querySelectorAll('[data-box-history]').forEach(b=>b.onclick=()=>openBoxHistory(state.boxes.find(x=>x.id===b.dataset.boxHistory)));app.querySelectorAll('[data-goal-toggle]').forEach(b=>b.onclick=async()=>{const g=state.goals.find(x=>x.id===b.dataset.goalToggle),done=!g.is_completed;g.is_completed=done;g.completed_at=done?new Date().toISOString():null;render();const{data,error}=await db.from('goals').update({is_completed:done,completed_at:g.completed_at}).eq('id',g.id).select('id').single();if(error||!data){g.is_completed=!done;render();safeError(error||new Error('Meta não foi atualizada.'))}else toast(done?'Meta concluída ✓':'Meta reaberta.')});app.querySelectorAll('[data-edit-goal]').forEach(b=>b.onclick=()=>openGoal(state.goals.find(x=>x.id===b.dataset.editGoal)));app.querySelector('[data-report-start]')?.addEventListener('change',e=>{state.reportStart=e.target.value;if(state.reportStart>state.reportEnd)state.reportEnd=state.reportStart;loadReport()});app.querySelector('[data-report-end]')?.addEventListener('change',e=>{state.reportEnd=e.target.value;if(state.reportEnd<state.reportStart)state.reportStart=state.reportEnd;loadReport()});app.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{const p=b.dataset.preset,end=currentMonth();state.reportEnd=end;if(p==='month')state.reportStart=end;else if(p==='year')state.reportStart=`${new Date().getFullYear()}-01-01`;else state.reportStart=addMonths(end,-(Number(p)-1));loadReport()});app.querySelectorAll('[data-category-filter]').forEach(b=>b.onclick=()=>{state.reportCategory=b.dataset.categoryFilter;render()})}

db.auth.onAuthStateChange(async(event,session)=>{const old=state.session?.user?.id;state.session=session;if(!session){state.profile=null;state.household=null;state.members=[];state.transactions=[];state.previousPending=[];state.unpaidOnly=false;state.monthRequest++;state.monthLoading=false;state.paymentBusy.clear();state.boxes=[];state.boxBalances=[];state.goals=[];state.cards=[];state.reportRows=[];state.reportTransactions=[];state.loading=false;render();return}if(event==='TOKEN_REFRESHED'||event==='INITIAL_SESSION')return;if(event==='USER_UPDATED'&&old===session.user.id){try{await loadContext();render()}catch(e){safeError(e)}return}if(event==='SIGNED_IN'||old!==session.user.id)await boot()});
async function init(){const{data:{session}}=await db.auth.getSession();state.session=session;if(session)await boot();else{state.loading=false;render()}}
init();
